Điều kiện dữ liệu:
where os.snapshot_date  = (select max(snapshot_date) from uat_vsdc_stg.outstanding_shares os1
							where snapshot_date < date_add(last_day(to_date(:p_year||'-'||lpad(:p_month,2,'0')||'-01')),1)
							)

where os.report_date  = (select max(report_date) from uat_vsdc_stg.foreign_investor_info os1
							where report_date < date_add(last_day(to_date(:p_year||'-'||lpad(:p_month,2,'0')||'-01')),1)
							)
